CREATE TABLE contact_consents(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN('service','marketing')),channel TEXT NOT NULL CHECK(channel IN('phone','sms','wechat','email','in_person')),recipient_label TEXT NOT NULL,address TEXT NOT NULL,source_note TEXT NOT NULL,effective_at TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(id,store_id,customer_id),FOREIGN KEY(customer_id,store_id) REFERENCES customers(id,store_id));

CREATE TABLE contact_consent_events(id TEXT PRIMARY KEY,consent_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('grant','revoke')),status TEXT NOT NULL CHECK(status IN('active','revoked')),note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(consent_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(consent_id,store_id,customer_id) REFERENCES contact_consents(id,store_id,customer_id),UNIQUE(consent_id,revision,store_id,customer_id));

CREATE TABLE contact_cases(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN('followup','pickup','training','other_service','marketing')),category TEXT NOT NULL CHECK(category IN('service','marketing')),source_json TEXT NOT NULL CHECK(json_valid(source_json)),cycle_id TEXT,cycle_version INTEGER,source_note TEXT NOT NULL,serial INTEGER NOT NULL,case_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(id,store_id,customer_id),UNIQUE(store_id,serial),FOREIGN KEY(customer_id,store_id) REFERENCES customers(id,store_id),FOREIGN KEY(cycle_id,cycle_version) REFERENCES cycle_versions(cycle_id,version),CHECK((cycle_id IS NULL AND cycle_version IS NULL) OR(cycle_id IS NOT NULL AND cycle_version IS NOT NULL)));

CREATE TABLE contact_case_events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','revise','assign','retry','defer','attempt','failed','resolve','cancel')),status TEXT NOT NULL CHECK(status IN('open','waiting','handoff','resolved','cancelled')),owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,purpose_note TEXT NOT NULL,due_at TEXT NOT NULL,next_action TEXT NOT NULL,attempt_id TEXT REFERENCES contact_attempts(id),resolution_reason TEXT,next_step TEXT,followup_task_id TEXT REFERENCES work_tasks(id),followup_revision INTEGER,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(case_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES contact_cases(id,store_id,customer_id),CHECK((followup_task_id IS NULL AND followup_revision IS NULL) OR(followup_task_id IS NOT NULL AND followup_revision IS NOT NULL)),CHECK((status IN('resolved','cancelled') AND resolution_reason IS NOT NULL AND next_step IS NOT NULL) OR(status NOT IN('resolved','cancelled') AND resolution_reason IS NULL AND next_step IS NULL AND followup_task_id IS NULL AND followup_revision IS NULL)));

CREATE TABLE contact_attempts(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,case_revision INTEGER NOT NULL,sequence INTEGER NOT NULL,consent_id TEXT NOT NULL,consent_revision INTEGER NOT NULL,occurred_at TEXT NOT NULL,result TEXT NOT NULL CHECK(result IN('attempted','sent','failed','no_answer','invalid_address','refused','connected')),source_note TEXT NOT NULL,content_summary TEXT NOT NULL,result_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(id,case_id,store_id,customer_id),UNIQUE(store_id,sequence),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES contact_cases(id,store_id,customer_id),FOREIGN KEY(case_id,case_revision) REFERENCES contact_case_events(case_id,revision),FOREIGN KEY(consent_id,consent_revision,store_id,customer_id) REFERENCES contact_consent_events(consent_id,revision,store_id,customer_id));

CREATE TABLE contact_receipts(id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,case_revision INTEGER NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('delivered','read','not_read','unknown','channel_failed')),source TEXT NOT NULL CHECK(source IN('staff_transcript','provider_transcript')),occurred_at TEXT NOT NULL,source_note TEXT NOT NULL,result_note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(attempt_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(attempt_id,case_id,store_id,customer_id) REFERENCES contact_attempts(id,case_id,store_id,customer_id),FOREIGN KEY(case_id,case_revision) REFERENCES contact_case_events(case_id,revision));

CREATE TABLE customer_appointments(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,cycle_id TEXT,cycle_version INTEGER,serial INTEGER NOT NULL,appointment_number TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(id,case_id,store_id,customer_id),UNIQUE(store_id,serial),FOREIGN KEY(case_id,store_id,customer_id) REFERENCES contact_cases(id,store_id,customer_id),FOREIGN KEY(cycle_id,cycle_version) REFERENCES cycle_versions(cycle_id,version),CHECK((cycle_id IS NULL AND cycle_version IS NULL) OR(cycle_id IS NOT NULL AND cycle_version IS NOT NULL)));

CREATE TABLE customer_appointment_events(id TEXT PRIMARY KEY,appointment_id TEXT NOT NULL,case_id TEXT NOT NULL,store_id TEXT NOT NULL,customer_id TEXT NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL,case_revision INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','reschedule','assign','cancel','no_show','arrive')),status TEXT NOT NULL CHECK(status IN('planned','cancelled','missed','arrived')),owner_id TEXT NOT NULL REFERENCES users(id),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,purpose_note TEXT NOT NULL,place_note TEXT NOT NULL,source_note TEXT NOT NULL,visit_id TEXT REFERENCES visits(id),arrived_at TEXT,note TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(appointment_id,revision),UNIQUE(store_id,sequence),FOREIGN KEY(appointment_id,case_id,store_id,customer_id) REFERENCES customer_appointments(id,case_id,store_id,customer_id),FOREIGN KEY(case_id,case_revision) REFERENCES contact_case_events(case_id,revision),CHECK((status='arrived' AND visit_id IS NOT NULL AND arrived_at IS NOT NULL) OR(status!='arrived' AND visit_id IS NULL AND arrived_at IS NULL)));

CREATE VIEW contact_journal AS SELECT store_id,sequence,created_at,'consent' kind,consent_id root_id,id FROM contact_consent_events UNION ALL SELECT store_id,sequence,created_at,'case',case_id,id FROM contact_case_events UNION ALL SELECT store_id,sequence,created_at,'attempt',case_id,id FROM contact_attempts UNION ALL SELECT store_id,sequence,created_at,'receipt',attempt_id,id FROM contact_receipts UNION ALL SELECT store_id,sequence,created_at,'appointment',appointment_id,id FROM customer_appointment_events;

CREATE VIEW contact_consent_current AS SELECT * FROM contact_consent_events e WHERE revision=(SELECT max(revision) FROM contact_consent_events WHERE consent_id=e.consent_id);

CREATE VIEW contact_case_current AS SELECT * FROM contact_case_events e WHERE revision=(SELECT max(revision) FROM contact_case_events WHERE case_id=e.case_id);

CREATE VIEW customer_appointment_current AS SELECT * FROM customer_appointment_events e WHERE revision=(SELECT max(revision) FROM customer_appointment_events WHERE appointment_id=e.appointment_id);

CREATE TRIGGER contact_consents_no_update BEFORE UPDATE ON contact_consents BEGIN SELECT RAISE(ABORT,'contact immutable history'); END;

CREATE TRIGGER contact_consents_no_delete BEFORE DELETE ON contact_consents BEGIN SELECT RAISE(ABORT,'contact immutable history'); END;

CREATE TRIGGER contact_consents_actor BEFORE INSERT ON contact_consents WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role IN('manager','reception','professional') AND u.active=1 AND coalesce(x.must_change_password,0)=0) OR (length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at) BEGIN SELECT RAISE(ABORT,'contact actor/time mismatch'); END;

CREATE TRIGGER contact_consent_events_no_update BEFORE UPDATE ON contact_consent_events BEGIN SELECT RAISE(ABORT,'contact immutable history'); END;

CREATE TRIGGER contact_consent_events_no_delete BEFORE DELETE ON contact_consent_events BEGIN SELECT RAISE(ABORT,'contact immutable history'); END;

CREATE TRIGGER contact_consent_events_actor BEFORE INSERT ON contact_consent_events WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security x ON x.user_id=u.id WHERE u.id=NEW.created_by AND u.store_id=NEW.store_id AND u.role IN('manager','reception','professional') AND u.active=1 AND coalesce(x.must_change_password,0)=0) OR (length(NEW.created_at)!=24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at) BEGIN SELECT RAISE(ABORT,'contact actor/time mismatch'); END;

CREATE TRIGGER contact_consent_events_sequence BEFORE INSERT ON contact_consent_events WHEN NEW.sequence!=(SELECT coalesce(max(sequence),0)+1 FROM contact_journal WHERE store_id=NEW.store_id) OR NEW.created_at<coalesce((SELECT max(created_at) FROM contact_journal WHERE store_id=NEW.store_id),NEW.created_at) OR (length(trim(NEW.reason)) NOT BETWEEN 1 AND 300 OR length(NEW.reason)>300) BEGIN SELECT RAISE(ABORT,'contact journal mismatch'); END;

